namespace ghidra.feature.vt.gui.actions;

using static ghidra.feature.vt.gui.plugin.VTPlugin;



using docking;
using docking.action;
using docking.tool;
using generic.theme;
using ghidra.feature.vt.api.db;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.task;
using ghidra.framework.model;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.task;

public class SaveVersionTrackingSessionAction : DockingAction {

	static readonly Icon ICON = new GIcon("icon.version.tracking.action.save.session");

	private VTController controller;

	public SaveVersionTrackingSessionAction(VTController controller) : base("Save", VTPlugin.OWNER)
    {
		this.controller = controller;

		setToolBarData(new ToolBarData(ICON, VT_MAIN_MENU_GROUP));
		setMenuBarData(
			new MenuData(new string[] { ToolConstants.MENU_FILE, "Save Session" }, ICON, "AAC"));
		setDescription("Save Version Tracking Changes");
		setEnabled(false);
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Version_Tracking_Tool"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		VTSession session = controller.getSession();
		if (session == null) {
			return;
		}

		if (session is VTSessionDB) {
			VTSessionDB sessionDB = (VTSessionDB) session;
			DomainFile vtDomainFile = sessionDB.getDomainFile();

			// Save version tracking session changes.
			SaveTask saveVersionTrackingTask = new SaveTask(vtDomainFile);
			TaskLauncher.launch(saveVersionTrackingTask);
			Program program = controller.getDestinationProgram();
			DomainFile destinationProgramFile = program.getDomainFile();
			if (destinationProgramFile.isChanged()) {
				SaveTask saveDestinationTask = new SaveTask(destinationProgramFile);
				TaskLauncher.launch(saveDestinationTask);
			}

			controller.refresh();
		}
	}

	private bool hasUnsavedVersionTrackingChanges() {
		// Check to see if there are unsaved changes to the results.
		VTSession session = controller.getSession();
		if (session == null) {
			return false;
		}
		if (session is VTSessionDB) {
			VTSessionDB sessionDB = (VTSessionDB) session;
			if (sessionDB.isChanged()) {
				return true;
			}
		}
		Program destinationProgram = controller.getDestinationProgram();
		return destinationProgram.isChanged();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return hasUnsavedVersionTrackingChanges();
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		return true;
	}

}
